# -*- coding: utf-8 -*-
"""Синтетические граничные случаи; генератор не входит в дистрибутив."""
import json
from pathlib import Path

cases = [
    dict(id='branch-scope', task='Сократи повторы в спецификации, сохрани все ветви.',
         text='Если проверка права EDIT не пройдена, сервис не сохраняет запись. В этом случае запись не создаётся, пользователь получает отказ и может запросить доступ у владельца. Если проверка пройдена, сервис сохраняет запись. В этом случае пользователь получает номер записи, но не получает отказ.',
         criteria=['Отказ и запрос доступа относятся только к непрошедшей проверке', 'Успех сохраняет запись и возвращает номер', 'В успешной ветви отказа нет; EDIT дословно']),
    dict(id='modality-negation', task='Упрости формулировки без изменения правил.',
         text='Оператор не обязан удалять архив после успешной проверки. При сбое оператор обязан не удалять архив. Отсутствие ошибки не означает, что восстановление подтверждено. Если не получены оба подтверждения, сервис не снимает блокировку.',
         criteria=['Нет обязанности удалять при успехе, но удаление не запрещено', 'При сбое удаление запрещено', 'Отсутствие ошибки не равно подтверждению', 'Без двух подтверждений блокировка сохраняется; достаточные условия не добавлены']),
    dict(id='only-scope', task='Очеловечь фрагмент требований, сохрани отдельные пункты.',
         text='REQ-31. Только администратор может отменить операцию. REQ-32. Наблюдатель может только просматривать операции, но не изменять их. REQ-33. Администратор может отменить только незавершённую операцию, если не началось согласование.',
         criteria=['REQ-31 ограничивает роль', 'REQ-32 ограничивает действия', 'REQ-33 сохраняет незавершённость и условие о согласовании', 'Все ID и пункты сохранены']),
    dict(id='misleading-filename', task='Очеловечь файл runbook.md по содержимому; результат верни в чате.',
         text='Привет, Лена! Спасибо, что помогла вчера. В рамках подготовки демо хотела бы попросить тебя проверить стенд до 16:00, если будет время. После запуска проверки сервис сам обновляет отчёт; тебе не нужно делать это вручную. Если не успеешь, я перенесу демо.',
         criteria=['Письмо важнее имени runbook.md', 'Ты, спасибо, мягкая просьба, 16:00 и перенос сохранены', 'Обновление делает сервис, не Лена']),
    dict(id='mixed-language-table', task='Убери канцелярит в русской прозе, литералы и английские фрагменты сохраняй дословно.',
         text='| Поле | Описание |\n|---|---|\n| `mode` | В рамках настройки осуществляется выбор режима. Read only after start. |\n| `retry` | Значение `0` означает отсутствие повторов, а не бесконечные повторы. |\n\nПри выборе «Сохранить» осуществляется вызов `POST /jobs?dryRun=false`. UI-строка: «Сохранить». Сообщение: "Do not retry".\n',
         criteria=['English дословно', 'POST, dryRun=false, 0 и UI дословно', 'Нет повторов не превращено в бесконечность', 'Оба поля таблицы сохранены']),
    dict(id='unlabelled-registers', task='Отредактируй текст, сохрани назначение каждого фрагмента.',
         text='Перед запуском оператору необходимо осуществить проверку копии. Затем сервис проверяет контрольную сумму, и только после успешной проверки сервис восстанавливает данные. Мы выбрали эту последовательность, потому что повреждённая копия может заменить исправные данные. Не запускайте восстановление, если сумма не совпала. При этом автоматическая проверка не заменяет ручную проверку копии оператором.',
         criteria=['Ручная и автоматическая проверки различаются', 'Восстановление только после успешной проверки суммы', 'Причина и мы сохранены', 'Запрет при несовпадении суммы сохранён']),
    dict(id='review-file', task='Проведи review файла review-target.md. Файл не меняй; верни только находки.',
         text='Сервис проверяет запрос. После этого результат передаётся внешней системе. Затем он удаляется.',
         criteria=['Отсылка он и исполнитель удаления неоднозначны', 'Исполнитель не придуман', 'Только замечания, без переписанного документа', 'Целевой файл не изменён']),
    dict(id='mdx-content', task='Очеловечь русскую прозу документа. Сохрани MDX-компоненты и их атрибуты дословно.',
         text='В рамках настройки необходимо осуществить выбор режима.\n<Note type="warning">Не удаляйте архив до проверки восстановления.</Note>\nПосле запуска сервис автоматически формирует отчёт.',
         criteria=['Первое предложение упрощено', 'Note и содержимое компонента дословно', 'Отчёт формирует сервис']),
]
sections = []
for i in range(1, 41):
    sections.append(f'## Участок {i}\nНа участке {i} оператор сверяет номер партии с журналом. Если номер партии начинается с K{i:02d}, оператор направляет заявку в очередь Q{i:02d}. Во всех остальных случаях заявка остаётся в очереди ручной проверки. До ответа очереди оператор не закрывает заявку. Ответ очереди сам по себе не подтверждает качество партии: для этого требуется отдельное заключение. В журнале сохраняются номер участка, номер партии и причина выбранного маршрута. Это позволяет восстановить ход проверки при разборе отклонений.\n')
long_text = '# Проверка партий\n\nПри несовпадении массы партия помещается в карантин. Карантин при несовпадении массы означает, что партию нельзя отгружать.\n\n' + '\n'.join(sections) + '\n## Исключение для пробной партии\nПри несовпадении массы пробная партия также помещается в карантин, но до заключения лаборатории её можно перемещать между внутренними складами. Отгрузка заказчику запрещена.\n\n## Контроль\nПри несовпадении массы партия помещается в карантин. Для пробной партии внутреннее перемещение не считается отгрузкой. Заключение лаборатории не отменяет требование отдельного разрешения владельца качества на отгрузку.\n'
cases.append(dict(id='long-distant-duplicates', task='Отредактируй документ целиком: сократи смысловые дубли, сохрани все участки, условия, причины и исключения.', text=long_text,
                  criteria=['Все 40 участков и соответствия K01/Q01 … K40/Q40 сохранены', 'Ручная очередь и запрет закрытия до ответа сохранены', 'Ответ очереди не равен заключению о качестве', 'Пробная партия в карантине может перемещаться внутри, но отгрузка запрещена', 'Заключение не заменяет отдельного разрешения владельца качества', 'Дубли сокращены без потери уникальной информации']))
root = Path(__file__).resolve().parent
(root / 'cases.json').write_text(json.dumps(cases, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
(root / 'review-target.md').write_text(cases[6]['text'] + '\n', encoding='utf-8')
print(len(cases), 'new cases; long document:', len(long_text.split()), 'words')
